#include "KS/SRC/stringx.h"
#include "KS/SRC/ks/igo_widget_analogclock.h"

#define NULL 0
#define NEW new(0, __FILE__, 0)

void *operator new(unsigned int, unsigned int, const char *, int);

bool TIMER_IsInfiniteDuration();
float TIMER_GetRemainingLevelSec();

class Font
{
public:
	enum HORIZJUST { HORIZJUST_RIGHT = 2 };
	enum VERTJUST { VERTJUST_BOTTOM = 2 };
};

typedef unsigned int color32;

class PanelQuad
{
	char data[404];
public:
	virtual ~PanelQuad();
	PanelQuad(stringx);
};

class PanelQuad4 : public PanelQuad
{
};

class TextString
{
	char data[76];
public:
	TextString(Font *, stringx, float, float, int, float, Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

extern const color32 COLOR_SCORE;

AnalogClockWidget::AnalogClockWidget()
{
	int	i;

	clockSec = TIMER_IsInfiniteDuration() ? 0 : TIMER_GetRemainingLevelSec();
	if (clockSec < 0.0f) clockSec = 0.0f;
	clockMin = (int) (clockSec / 60);
	clockSec -= clockMin * 60;

	clockHandPQ = NULL;
	clockFramePQ = NULL;
	clockFacePQ = NULL;
	num1PQ = NULL;
	num2PQ = NULL;
	num3PQ = NULL;
	num4PQ = NULL;
	num5PQ = NULL;
	infPQ = NULL;

	// Allocate analog clock time segments.
	for (i = 0; i < 60; i++)
	{
		timeSegs[i] = NEW PanelQuad4("");
	}

	score = 0;
	scoreText = NEW TextString(NULL, GetScoreText(score), 522, 63, 0, 1.0f, Font::HORIZJUST_RIGHT, Font::VERTJUST_BOTTOM, COLOR_SCORE);

	elapsedInterval = 0.0f;
}
